-- PE10 v0.2: append-only reusable root causes; no profile activation.
-- ACT-0001 -> ACTUALIZACION_DB_LF -> Migration Merge Train only.
BEGIN;
DO $pe10_ekb$
DECLARE n integer;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-PE10-V02-SCHEMA-VALIDATOR-PARITY-20261015-001') THEN
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,created_at,updated_at,primera_vez,ultima_vez)
 VALUES(gen_random_uuid(),'LF-PE10-V02-SCHEMA-VALIDATOR-PARITY-20261015-001','PROFILE_EVOLUTION','El esquema declarado y el validador de Product Director difieren en salidas reales','El validador canónico product_director_lf aceptó el RAW evolucionado de PESC3-V2-212 T3, pero la validación transversal contra schemas/product_direction_spec.schema.json lo rechazó por campos requeridos ausentes y propiedades raíz no declaradas. El RAW original T3 también falla el esquema; UI R2 sí pasó ambos controles. No relajar esquema para fabricar PASS.','La evolución de outputs y validador no mantuvo paridad con el esquema de la modalidad PRODUCT_DIRECTION_SPEC. El validador no exige todos los campos que el schema declara y acepta propiedades adicionales que el schema rechaza.','Validador especializado informa cero errores pero JSON Schema declarado del mismo perfil no valida la misma salida; un sistema que use un único control puede emitir un falso PASS.','En Profile Creator/Updater ejecutar el esquema canónico y el validador local actuales sobre una salida materializada, con igualdad de refs y SHA. Rechazar discrepancias antes de admisión y resolver con el propietario del contrato, sin inferir schemas por nombre ni generar nuevas baterías. Reutilizar run_bound_profile_output_validator_v1.py.','Prueba exacta desde main: UI_B_R2 -> CANDIDATE_OUTPUT_PARITY_OBSERVED; PRODUCT_A_T3 -> EXPECTED_NEGATIVE_REJECTED_BY_SHAPE; PRODUCT_B_T3 -> OUTPUT_SHAPE_INVALID aunque el validador específico anterior dio cero errores. Capturas inmutables eventos 21041,21044,21047; PR #2734 registra veto v0.2.','HIGH',1,'PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3','2732;2734','ACTIVO','supabase://public.lf_eventos/21041;supabase://public.lf_eventos/21044;supabase://public.lf_eventos/21047','construction',ARRAY['Architect']::text[],'R2_NO_VE','LOUD_EARLY','PROFILE_UPDATER_CANONICAL_OUTPUT_PARITY','https://github.com/cristhianlujan/claude-persona-lf-patch/pull/2734',clock_timestamp(),clock_timestamp(),clock_timestamp(),clock_timestamp());
 END IF;
 SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo='LF-PE10-V02-SCHEMA-VALIDATOR-PARITY-20261015-001'
  AND causa_raiz='La evolución de outputs y validador no mantuvo paridad con el esquema de la modalidad PRODUCT_DIRECTION_SPEC. El validador no exige todos los campos que el schema declara y acepta propiedades adicionales que el schema rechaza.' AND prevencion='En Profile Creator/Updater ejecutar el esquema canónico y el validador local actuales sobre una salida materializada, con igualdad de refs y SHA. Rechazar discrepancias antes de admisión y resolver con el propietario del contrato, sin inferir schemas por nombre ni generar nuevas baterías. Reutilizar run_bound_profile_output_validator_v1.py.'
  AND detectability='LOUD_EARLY' AND root_cause_family='R2_NO_VE';
 IF n<>1 THEN RAISE EXCEPTION 'PE10_V02_EKB_MISMATCH_1'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-PE10-V02-SQL-PATCH-INTERPOLATION-20261015-001') THEN
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,created_at,updated_at,primera_vez,ultima_vez)
 VALUES(gen_random_uuid(),'LF-PE10-V02-SQL-PATCH-INTERPOLATION-20261015-001','PROFILE_EVOLUTION','Interpolación de reemplazo de texto duplicó el candidato SQL en una rama','Durante construcción local de un parche del registrador candidato v0.2, String.replace con reemplazo como cadena interpretó secuencias dólar-comilla de expresiones SQL como sufijo del texto y generó duplicación. Se detectó por tamaño, diff y recuento de terminadores; se restauraron ambos archivos al blob idéntico de main antes de un nuevo parche con callback. Ningún SQL se aplicó a la DB ni se fusionó.','Uso de JavaScript String.replace con segundo argumento cadena sobre contenido SQL que incluye el patrón especial dólar-apóstrofe, expandiendo el texto restante del fichero.','Diff muestra duplicación después de $function$ y tamaño duplicado, aunque un reemplazo pequeño era lo esperado; el candidato no compila y no debe entrar a Train.','Usar función callback en replace para insertar cadenas SQL literales, verificar delta de longitud, terminador exacto, número de declaraciones y diff main-versus-branch antes de PR. Revertir blob afectado ante anomalía, no aplicar ni repetir en producción.','Ambos archivos SQL restaurados al blob principal y el nuevo candidato comprobó un único CREATE OR REPLACE FUNCTION, terminador único, 15 pruebas estáticas PASS, 3 archivos de diff. GitHub PR #2734 contiene solo cambios acotados.','MEDIUM',1,'PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3','2734','ACTIVO','github://cristhianlujan/claude-persona-lf-patch/pull/2734','construction',ARRAY['Architect']::text[],'R2_NO_VE','LOUD_EARLY','SQL_SOURCE_PATCH_GENERATION','https://github.com/cristhianlujan/claude-persona-lf-patch/pull/2734',clock_timestamp(),clock_timestamp(),clock_timestamp(),clock_timestamp());
 END IF;
 SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo='LF-PE10-V02-SQL-PATCH-INTERPOLATION-20261015-001'
  AND causa_raiz='Uso de JavaScript String.replace con segundo argumento cadena sobre contenido SQL que incluye el patrón especial dólar-apóstrofe, expandiendo el texto restante del fichero.' AND prevencion='Usar función callback en replace para insertar cadenas SQL literales, verificar delta de longitud, terminador exacto, número de declaraciones y diff main-versus-branch antes de PR. Revertir blob afectado ante anomalía, no aplicar ni repetir en producción.'
  AND detectability='LOUD_EARLY' AND root_cause_family='R2_NO_VE';
 IF n<>1 THEN RAISE EXCEPTION 'PE10_V02_EKB_MISMATCH_2'; END IF;
END
$pe10_ekb$;
COMMIT;
